-- MariaDB 12 compatible conversion of supplied PostgreSQL dump
-- Original public table names retained; prisma_contract tables prefixed to fit MySQL database namespaces.
SET NAMES utf8mb4;
SET FOREIGN_KEY_CHECKS=0;
CREATE DATABASE IF NOT EXISTS `dkkt` CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci;
USE `dkkt`;

CREATE TABLE IF NOT EXISTS `prisma_contract_contract` (
  `core_hash` VARCHAR(191) NOT NULL,
  `created_at` DATETIME DEFAULT CURRENT_TIMESTAMP NOT NULL,
  `contract_json` JSON NOT NULL
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE IF NOT EXISTS `prisma_contract_ledger` (
  `id` BIGINT NOT NULL AUTO_INCREMENT,
  `created_at` DATETIME DEFAULT CURRENT_TIMESTAMP NOT NULL,
  `space` LONGTEXT NOT NULL,
  `migration_name` LONGTEXT NOT NULL,
  `migration_hash` LONGTEXT NOT NULL,
  `origin_core_hash` LONGTEXT,
  `origin_profile_hash` LONGTEXT,
  `destination_core_hash` LONGTEXT NOT NULL,
  `destination_profile_hash` LONGTEXT,
  `operations` JSON NOT NULL,
  PRIMARY KEY (`id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE IF NOT EXISTS `prisma_contract_marker` (
  `space` VARCHAR(191) DEFAULT 'app' NOT NULL,
  `core_hash` LONGTEXT NOT NULL,
  `profile_hash` LONGTEXT NOT NULL,
  `contract_json` JSON,
  `canonical_version` INT,
  `updated_at` DATETIME DEFAULT CURRENT_TIMESTAMP NOT NULL,
  `app_tag` LONGTEXT,
  `meta` JSON DEFAULT ('{}') NOT NULL,
  `invariants` JSON DEFAULT ('[]') NOT NULL
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE IF NOT EXISTS `agenda` (
  `address` LONGTEXT,
  `categoryId` VARCHAR(191),
  `committeeId` VARCHAR(191),
  `contactEmail` LONGTEXT,
  `contactName` LONGTEXT,
  `contactPhone` LONGTEXT,
  `createdAt` DATETIME DEFAULT CURRENT_TIMESTAMP NOT NULL,
  `createdById` VARCHAR(191) NOT NULL,
  `description` LONGTEXT NOT NULL,
  `endDate` DATETIME,
  `endTime` LONGTEXT,
  `excerpt` LONGTEXT,
  `id` VARCHAR(191) NOT NULL,
  `image` LONGTEXT,
  `isFeatured` TINYINT(1) DEFAULT false NOT NULL,
  `isPublished` TINYINT(1) DEFAULT false NOT NULL,
  `location` LONGTEXT,
  `notes` LONGTEXT,
  `organizer` LONGTEXT,
  `publishedAt` DATETIME,
  `publishedById` VARCHAR(191),
  `registrationText` LONGTEXT,
  `registrationUrl` LONGTEXT,
  `rejectedAt` DATETIME,
  `rejectedById` VARCHAR(191),
  `rejectionReason` LONGTEXT,
  `reviewedAt` DATETIME,
  `reviewedById` VARCHAR(191),
  `slug` VARCHAR(191) NOT NULL,
  `startDate` DATETIME NOT NULL,
  `startTime` LONGTEXT,
  `status` VARCHAR(191) DEFAULT 'DRAFT' NOT NULL,
  `target` LONGTEXT,
  `title` LONGTEXT NOT NULL,
  `updatedAt` DATETIME DEFAULT CURRENT_TIMESTAMP NOT NULL,
  `updatedById` VARCHAR(191)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE IF NOT EXISTS `agendaCategory` (
